List<String> byDueDate(List<(String, String)> tasks) {
  final sorted = [...tasks]
    ..sort((a, b) {
      if (a.$2.isEmpty != b.$2.isEmpty) return a.$2.isEmpty ? 1 : -1;
      final byDate = a.$2.compareTo(b.$2);
      return byDate != 0 ? byDate : a.$1.compareTo(b.$1);
