import 'dart:io';

class Line {
  final String id;
  final int qty;
  const Line(this.id, this.qty);
}

List<Line> apply(List<Line> cart, String op, String id) {
  if (op == 'add') {
    if (!cart.any((l) => l.id == id)) return [...cart, Line(id, 1)];
    return [for (final l in cart) l.id == id ? Line(l.id, l.qty + 1) : l];
  }
  if (op == 'remove') return cart.where((l) => l.id != id).toList();
  return cart;
}

void main() {
  var cart = <Line>[];
  while (true) {
    final line = stdin.readLineSync();
    if (line == null) break;
    final parts = line.trim().split(' ');
    if (parts.length == 2) cart = apply(cart, parts[0], parts[1]);
  }
  print(cart.isEmpty ? '(empty)' : cart.map((l) => '${l.id} x${l.qty}').join('\n'));
}

