prompt:
A tag cloud uses `Wrap(spacing: s)`. Given the max width and spacing (line 1) and the children's widths
(line 2), print how many runs (lines) it takes. A child joins the current run if `used + spacing + width <= maxWidth`;
otherwise it starts a new run (a child wider than the max still gets its own run). No children → `0`. Fix `wrapRuns`.

coding.starterCode:
import 'dart:io';

int wrapRuns(List<double> widths, double spacing, double maxWidth) {
  final total = widths.fold(0.0, (a, b) => a + b);
  return (total / maxWidth).ceil();
}

void main() {
  final head = stdin.readLineSync()!.trim().split(' ').map(double.parse).toList();
  final line = (stdin.readLineSync() ?? '').trim();
  final widths = line.isEmpty ? <double>[] : line.split(' ').map(double.parse).toList();
  print(wrapRuns(widths, head[1], head[0]));
}

coding.referenceSolution:
import 'dart:io';

int wrapRuns(List<double> widths, double spacing, double maxWidth) {
  if (widths.isEmpty) return 0;
  var runs = 1;
  var used = widths.first;
  for (final w in widths.skip(1)) {
    if (used + spacing + w <= maxWidth) {
      used += spacing + w;
    } else {
      runs++;
      used = w;
    }
  }
  return runs;
}

void main() {
  final head = stdin.readLineSync()!.trim().split(' ').map(double.parse).toList();
  final line = (stdin.readLineSync() ?? '').trim();
  final widths = line.isEmpty ? <double>[] : line.split(' ').map(double.parse).toList();
  print(wrapRuns(widths, head[1], head[0]));
}

