List<int> backoff(int attempts, int baseMs, int maxMs) {
  final out = <int>[];
  var delay = baseMs;
  for (var n = 0; n < attempts; n++) {
    out.add(delay > maxMs ? maxMs : delay);
    if (delay < maxMs) delay *= 2;
  }
  return out;
}

