import 'dart:io';

Map<String, String> resolve(List<(String, String, int, String)> rows) {
  final best = <String, (String, int, String)>{};
  for (final (src, id, at, value) in rows) {
    final cur = best[id];
    if (cur == null || at > cur.$2 || (at == cur.$2 && src == 'S')) best[id] = (src, at, value);
  }
  return {
    for (final e in best.entries)
      if (e.value.$3 != '-') e.key: e.value.$3
  };
}

void main() {
  final rows = <(String, String, int, String)>[];
  while (true) {
    final line = stdin.readLineSync();
    if (line == null) break;
    final p = line.trim().split(' ');
    if (p.length == 4) rows.add((p[0], p[1], int.parse(p[2]), p[3]));
  }
  final out = resolve(rows);
  final ids = out.keys.toList()..sort();
  print(ids.isEmpty ? '(empty)' : ids.map((id) => '$id=${out[id]}').join('\n'));
